// Pure text-layer matching. Never claims OCR or semantic validation.
const numeric=new Set([92,93,94,96,99,100,101,103,106,107,108,109,110,111,112,113,114,115,116,117,119,129,131,136,137,138,141,142,143,146,147,148,149,152]);
const dates=new Set([2,7,9,26,72,73,74,134,135]);
const compact=new Set([30,31,32,47,48,63,84,86,90,91,157]);
const codes=new Set([3,5,6,8,21,23,24,39,40,54,55,68,69,79,80,81,95,98,102,105,118,121,126,130,140,145,150,151,158,159]);
export function normalize(s){return String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[’‘]/g,"'").toLowerCase().replace(/\s+/g,' ').trim();}
export function numberKey(s){s=String(s).replace(/[−–]/g,'-').trim().replace(/(?:EUR|USD|GBP|€|\$|£|%)/gi,'').replace(/[\s\u00a0\u202f']/g,'');if(!/^[+-]?\d[\d.,]*$/.test(s))return null;const dot=s.lastIndexOf('.'),comma=s.lastIndexOf(',');if(dot>=0&&comma>=0){const decimal=dot>comma?'.':',';s=s.replace(decimal==='.'?/,/g:/\./g,'').replace(',','.');}else if(comma>=0)s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?String(n):null;}
function dateKey(s){s=String(s).trim();let m;if((m=s.match(/^(\d{4})-?(\d{2})-?(\d{2})$/)))return m[1]+m[2]+m[3];if((m=s.match(/^(\d{2})[/.\-](\d{2})[/.\-](\d{4})$/)))return m[3]+m[2]+m[1];return null;}
function equal(record,text){if(numeric.has(record.id))return numberKey(text)!==null&&numberKey(text)===numberKey(record.value);if(dates.has(record.id))return dateKey(text)!==null&&dateKey(text)===dateKey(record.value);if(compact.has(record.id))return normalize(text).replace(/[\s.\-]/g,'')===normalize(record.value).replace(/[\s.\-]/g,'');return normalize(text)===normalize(record.value);}
function valueInSpan(r,text){if(equal(r,text))return true;if(dates.has(r.id))return [...text.matchAll(/\b(?:\d{4}-\d{2}-\d{2}|\d{2}[/.-]\d{2}[/.-]\d{4}|\d{8})\b/g)].some(m=>equal(r,m[0]));if(numeric.has(r.id))return [...text.matchAll(/(?<![\p{L}\p{N}./-])[-+−]?\d(?:[\d.,\u00a0\u202f ]*\d)?(?![\p{L}\p{N}/])/gu)].some(m=>equal(r,m[0]));return false;}
function matrix(a,b){return [a[0]*b[0]+a[2]*b[1],a[1]*b[0]+a[3]*b[1],a[0]*b[2]+a[2]*b[3],a[1]*b[2]+a[3]*b[3],a[0]*b[4]+a[2]*b[5]+a[4],a[1]*b[4]+a[3]*b[5]+a[5]];}
export function textSpans(content,viewport,page){const result=[];for(const item of content.items){if(!item.str?.trim()||!item.transform)continue;const m=matrix(viewport.transform,item.transform);const angle=Math.atan2(m[1],m[0]);const height=Math.hypot(m[2],m[3]);const width=item.width*viewport.scale;const ascent=content.styles?.[item.fontName]?.ascent??.8;const ax=Math.sin(angle)*height*ascent,ay=-Math.cos(angle)*height*ascent;const x=m[4]+ax,y=m[5]+ay;const pts=[[x,y],[x+Math.cos(angle)*width,y+Math.sin(angle)*width],[x-Math.sin(angle)*height,y+Math.cos(angle)*height],[x+Math.cos(angle)*width-Math.sin(angle)*height,y+Math.sin(angle)*width+Math.cos(angle)*height]];const left=Math.max(0,Math.min(...pts.map(p=>p[0]))),top=Math.max(0,Math.min(...pts.map(p=>p[1])));result.push({text:item.str,page,x:left/viewport.width,y:top/viewport.height,width:Math.min(viewport.width-left,Math.max(...pts.map(p=>p[0]))-left)/viewport.width,height:Math.min(viewport.height-top,Math.max(...pts.map(p=>p[1]))-top)/viewport.height,rotated:Math.abs(Math.sin(angle))>.1});}return result;}
function windows(spans){const out=[];const sorted=[...spans].sort((a,b)=>a.page-b.page||a.y-b.y||a.x-b.x);const lines=[];for(const s of sorted){let line=lines.findLast(l=>l[0].page===s.page&&!s.rotated&&!l[0].rotated&&Math.abs(l[0].y-s.y)<Math.max(l[0].height,s.height)*.45);if(!line){line=[];lines.push(line);}line.push(s);}for(const line of lines){line.sort((a,b)=>a.x-b.x);for(let i=0;i<line.length;i++){let text='',left=line[i].x,top=line[i].y,right=left,bottom=top;for(let j=i;j<Math.min(i+8,line.length);j++){const s=line[j];if(j>i&&s.x-right>.045)break;text+=(j>i?' ':'')+s.text;right=Math.max(right,s.x+s.width);top=Math.min(top,s.y);bottom=Math.max(bottom,s.y+s.height);out.push({text,page:s.page,x:left,y:top,width:right-left,height:bottom-top});}}}return out;}
export function matchRecords(records,spans){const pool=windows(spans);return records.map((r,index)=>{if(codes.has(r.id)||(!numeric.has(r.id)&&!dates.has(r.id)&&normalize(r.value).length<3))return {record:index,status:'unsupported',candidates:[]};const found=[];for(const span of pool){let match=valueInSpan(r,span.text);if(!match&&!numeric.has(r.id)&&!dates.has(r.id)&&!compact.has(r.id)){const text=normalize(span.text),v=normalize(r.value);const at=text.indexOf(v);match=at>=0&&v.length>=5&&(!at||!/[\p{L}\p{N}_./-]/u.test(text[at-1]))&&(at+v.length===text.length||!/[\p{L}\p{N}_./-]/u.test(text[at+v.length]));}if(match){const existing=found.findIndex(f=>f.page===span.page&&Math.abs(f.x-span.x)<.003&&Math.abs(f.y-span.y)<.004);if(existing<0)found.push(span);else if(span.width<found[existing].width)found[existing]=span;}}
 // Same value attached to several business terms cannot be assigned semantically without review.
 const shared=records.some((other,i)=>i!==index&&equal(r,other.value));
 return {record:index,status:found.length===0?'missing':found.length===1&&!shared?'unique':'ambiguous',shared,candidateCount:found.length,candidates:found};});}
